void check(bool value, const char* message) {
    if (!value) throw std::runtime_error(message);
}

void near(double actual, double expected, double tolerance, const char* message) {
    if (!std::isfinite(actual) || std::abs(actual - expected) > tolerance) {
        throw std::runtime_error(std::string(message) + ": actual=" + std::to_string(actual) +
                ", expected=" + std::to_string(expected));
    }
}

template<typename F>
void rejects(F action) {
    try {
        action();
    } catch (const std::invalid_argument&) {
        return;
    }
    throw std::runtime_error("invalid input was accepted");
}

std::vector<Transient> sample_positions(std::initializer_list<long long> positions) {
    std::vector<Transient> events;
    for (auto position : positions) events.push_back({position / 44100.0, 1, 0});
    return events;
}

std::vector<Transient> pulses(double bpm, double phase, int count, double jitter = 0) {
    std::vector<Transient> events;
    for (int i = 0; i < count; ++i) {
        events.push_back({phase + i * 60 / bpm + jitter * std::sin(i * 0.7),
                i % 4 ? 1.0 : 2.0, i % 4 ? 0.2 : 1.0});
    }
    return events;
}

void validate_domains() {
    validate_transients({});
    validate_transients({{0, 0, 0}, {0, 1, 1}});
    for (double bad : {-1.0, std::numeric_limits<double>::infinity(),
                 std::numeric_limits<double>::quiet_NaN()}) {
        rejects([&] { validate_transients({{bad, 1, 1}}); });
        rejects([&] { validate_transients({{0, bad, 1}}); });
        rejects([&] { validate_transients({{0, 1, bad}}); });
    }
    rejects([] { validate_transients({{1, 1, 1}, {0, 1, 1}}); });
    rejects([] { phase_histogram({}, 0, 0, 32); });
    rejects([] { phase_histogram({}, 1, 0, 0); });
    rejects([] { phase_histogram({}, 1, 0, 1000000); });
    rejects([] { correct_phase({}, 0, 0); });
    rejects([] { tempo_consensus({120, 0}); });
}

void interval_gates() {
    check(interval_votes(sample_positions({0, 11000})).empty(), "lower excluded interval");
    check(interval_votes(sample_positions({0, 11001})).size() == 1, "lower inclusive interval");
    check(interval_votes(sample_positions({0, 54999})).size() == 1, "upper inclusive interval");
    check(interval_votes(sample_positions({0, 55000})).empty(), "upper excluded interval");
    const auto groups = interval_votes(sample_positions({0, 100, 200, 300, 400, 20000}));
    check(!groups.empty() && groups.front().reference_samples == 19900,
            "fifth successor must not form the first representative");
    rejects([] { interval_votes({}, 1, 0); });
}

void interval_representatives_and_weights() {
    auto events = sample_positions({0, 12000, 24250, 36375});
    const auto groups = interval_votes(events);
    const auto get = [&](long long value) {
        auto it = std::find_if(groups.begin(), groups.end(),
                [value](const auto& group) { return group.reference_samples == value; });
        check(it != groups.end(), "expected fixed interval representative");
        return it->votes;
    };
    check(get(12000) == 2 && get(12250) == 2,
            "one interval must be allowed to vote into overlapping groups");
    for (auto& event : events) event.weight *= 100000;
    const auto changed = interval_votes(events);
    check(changed.size() == groups.size(), "amplitude must not alter interval groups");
    for (std::size_t i = 0; i < groups.size(); ++i) {
        check(changed[i].votes == groups[i].votes, "votes must be counts");
        check(changed[i].reference_samples == groups[i].reference_samples,
                "representatives must not move");
    }
}

void interval_time_scale_and_windows() {
    auto events = pulses(120, 4.2, 8);
    const auto a = interval_votes(events, 4, 8);
    for (auto& event : events) event.time_seconds -= 4;
    const auto b = interval_votes(events, 0, 4);
    check(a.size() == b.size(), "window start must affect reference clock only");
    for (std::size_t i = 0; i < a.size(); ++i) {
        check(a[i].reference_samples == b[i].reference_samples && a[i].votes == b[i].votes,
                "44100-reference intervals must be shift invariant");
    }
}

