void histogram_kernel_and_circularity() {
    const auto histogram = phase_histogram({{0, 1, 100}}, 1, 0, 32);
    near(histogram.bins[0], 1, 0, "kernel centre");
    for (int distance = 1; distance <= 4; ++distance) {
        near(histogram.bins[distance], 1 - 0.2 * distance, 1e-14, "positive kernel side");
        near(histogram.bins[32 - distance], 1 - 0.2 * distance, 1e-14, "negative circular side");
    }
    near(histogram.bins[5], 0, 0, "reported +5 write has zero weight");
    near(histogram.total_weight, 5, 1e-14, "kernel mass");
    const auto shifted = phase_histogram({{0.125, 1, 1}}, 1, 1, 32);
    const auto unshifted = phase_histogram({{0.125, 1, 1}}, 1, 0, 32);
    check(shifted.bins == unshifted.bins, "whole-period folding invariance");
    const auto additive = phase_histogram({{0.125, 1, 1}}, 1, 0.125, 32);
    check(additive.peak_bin == 8, "histogram offset uses time PLUS offset");
    rejects([] { phase_histogram({{0.1, 1, 0}}, 1, -0.2, 32); });
}

void histogram_score_scaling_and_purity() {
    const auto events = pulses(120, 0.2, 40);
    const auto a = phase_histogram(events, 0.5, 0, 64);
    auto scaled = events;
    for (auto& event : scaled) {
        event.weight *= 3;
        event.bass_weight *= 50;
    }
    const auto b = phase_histogram(scaled, 0.5, 0, 64);
    near(b.variance, 9 * a.variance, 1e-8, "weight scaling must square score scaling");
    check(a.bins == phase_histogram(events, 0.5, 0, 64).bins,
            "histogram calls must not retain stale accumulation");
    const auto empty = phase_histogram({}, 0.5, 0, 64);
    near(empty.variance, 0, 0, "empty histogram");
    rejects([] { phase_histogram({{0, 1e308, 0}, {0, 1e308, 0}}, 1, 0, 64); });
}

